// 이번 단계(depth)에서 방문할 URL 목록을 정리합니다.
// 시트 1에서 처음 호출되면 depth=0 (DDG 검색 URL), 재귀 호출이면 depth>=1
const MAX_DEPTH = 6;        // 비상 브레이크: 정상적인 양판점이면 닿지 않는 깊이
const MAX_PER_LEVEL = 15;   // 한 단계에서 여는 최대 페이지 수 (크레딧 보호)

const items = $input.all().map(i => i.json).filter(j => j && j.url && !j._noop);
if (!items.length) return [];

const first = items[0];
const depth = Number(first.depth || 0);
if (depth > MAX_DEPTH) return [];

const visited = new Set(first.visited || []);

// 기준 도메인: DDG URL의 site:도메인, 없으면 URL 호스트
let rootDomain = first.root_domain || '';
if (!rootDomain) {
  try {
    const m = decodeURIComponent(first.url).match(/site:([^\s+&]+)/);
    rootDomain = (m ? m[1] : new URL(first.url).hostname).replace(/^www\./, '');
  } catch (e) {
    rootDomain = '';
  }
}

const picked = [];
for (const j of items) {
  const url = String(j.url).trim();
  if (visited.has(url)) continue;
  visited.add(url);
  picked.push({ ...j, url });
  if (picked.length >= MAX_PER_LEVEL) break;
}

const visitedArr = [...visited];
return picked.map(j => ({
  json: {
    url: j.url,
    depth,
    root_domain: rootDomain,
    keyword: j.keyword || '',
    original_keyword: j.original_keyword || j.keyword || '',
    category: j.category || 'E-commerce',
    site_name: j.site_name || rootDomain || 'External_Site',
    country: j.country || '',
    visited: visitedArr
  }
}));

// 스크래핑 결과 정리. DDG 검색결과는 AI 없이 코드로 링크를 뽑습니다.
const src = $('입력 정리').item.json;
const md = $json.markdown || '';
const isDdg = src.url.includes('duckduckgo.com');

let ddgLinks = [];
if (isDdg) {
  ddgLinks = [...md.matchAll(/uddg=([^&)\s]+)/g)]
    .map(m => { try { return decodeURIComponent(m[1]); } catch (e) { return ''; } })
    .filter(u => u.startsWith('http') && !u.includes('duckduckgo.com/y.js'));  // 광고 제외
  ddgLinks = [...new Set(ddgLinks)];
}

const scrapeError = md ? null : String($json.error?.message || $json.message || 'empty markdown');

return {
  json: {
    ...src,
    is_ddg: isDdg,
    ddg_links: ddgLinks,
    scrape_error: scrapeError,
    page_markdown: isDdg
      ? '(검색엔진 결과 페이지 - 판정 불필요. IRRELEVANT로 응답)'
      : (md.substring(0, 30000) || '(빈 페이지)')
  }
};

// AI 판정 결과를 리뷰 행(reviews)과 다음 단계 링크(next)로 나눕니다.
const LINKS_PER_PAGE = 5;
const pages = $('페이지 준비').all().map(i => i.json);

function makeHash(str) {
  let h = 0;
  const s = String(str).trim();
  for (let i = 0; i < s.length; i++) { h = ((h << 5) - h) + s.charCodeAt(i); h |= 0; }
  return Math.abs(h).toString(36);
}

function normalize(link, base) {
  if (typeof link !== 'string') return '';
  let u = link.trim().replace(/^<|>$/g, '');
  const md = u.match(/\]\((.+)\)$/);          // [text](url) 형태로 오면 url만
  if (md) u = md[1];
  const uddg = u.match(/uddg=([^&]+)/);
  if (uddg) { try { u = decodeURIComponent(uddg[1]); } catch (e) {} }
  try {
    const parsed = new URL(u, base);
    parsed.hash = '';
    return parsed.href;
  } catch (e) {
    return '';
  }
}

const reviews = [];
const nextMap = new Map();
const log = [];

$input.all().forEach((item, i) => {
  const p = pages[i];
  if (!p) return;

  let type = 'IRRELEVANT';
  let revs = [];
  let links = [];

  if (p.is_ddg) {
    type = 'SEARCH';
    // 기사/랭킹/블로그보다 제품 페이지(숫자 ID 경로)를 먼저 방문
    const isArticle = u => /magazyn|blog|poradnik|artyku|ranking|news|guide|ratgeber|forum/i.test(u);
    const hasId = u => /\/\d{5,}/.test(u);
    links = [...(p.ddg_links || [])].sort((a, b) => (isArticle(a) - isArticle(b)) || (hasId(b) - hasId(a)));
  } else {
    const raw = String(item.json.text || item.json.output || '{}');
    try {
      const m = raw.match(/\{[\s\S]*\}/);
      const parsed = JSON.parse(m ? m[0] : raw);
      type = String(parsed.page_type || 'IRRELEVANT').toUpperCase();
      revs = Array.isArray(parsed.reviews) ? parsed.reviews : [];
      links = Array.isArray(parsed.next_links) ? parsed.next_links : [];
    } catch (e) {
      type = 'PARSE_ERROR';
    }
  }

  for (const v of revs) {
    if (!v || !v.content) continue;
    reviews.push({
      voc_id: `EXT_${makeHash(p.url + String(v.content).substring(0, 120))}`,
      source_site: p.site_name || 'External_Site',
      category: p.category || 'E-commerce',
      content_type: v.content_type || 'REVIEW',
      content: String(v.content),
      parent_id: p.url,
      published_at: v.published_at || null
    });
  }

  const visited = new Set(p.visited || []);
  let added = 0;
  const skip = { bad_url: 0, visited: 0, other_domain: [] };  // 링크가 왜 탈락했는지 (디버깅용)
  let root = String(p.root_domain || '').replace(/^www\./, '');
  if (root.includes('duckduckgo')) root = '';  // site: 파싱 실패로 DDG 호스트가 들어오면 모든 링크가 탈락하므로 무시
  if (type !== 'IRRELEVANT' && type !== 'PARSE_ERROR') {
    for (const l of links) {
      if (added >= (p.is_ddg ? 8 : LINKS_PER_PAGE)) break;
      const url = normalize(l, p.url);
      if (!url.startsWith('http')) { skip.bad_url++; continue; }
      if (visited.has(url) || nextMap.has(url)) { skip.visited++; continue; }
      let host = '';
      try { host = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { skip.bad_url++; continue; }
      if (host.includes('duckduckgo')) { skip.other_domain.push(host); continue; }  // DDG 광고/내부 링크
      if (root && !host.endsWith(root)) { skip.other_domain.push(host); continue; }  // 양판점 밖으로 나가지 않음
      nextMap.set(url, {
        url,
        depth: p.depth + 1,
        root_domain: root || host,
        keyword: p.keyword,
        original_keyword: p.original_keyword,
        category: p.category,
        site_name: p.site_name,
        country: p.country,
        visited: p.visited
      });
      added++;
    }
  }

  log.push({ depth: p.depth, url: p.url, type, reviews: revs.length, next_links: added, error: p.scrape_error, root_domain: p.root_domain, candidates: links.length, skip });
});

return [{ json: { reviews, next: [...nextMap.values()], log } }];

// 다음 단계로 넘길 링크를 아이템으로 펼칩니다. 없으면 재귀 호출이 즉시 끝나도록 _noop 1개.
const next = $input.first().json.next || [];
if (!next.length) return [{ json: { _noop: true } }];
return next.map(json => ({ json }));

// 이번 단계에서 얻은 리뷰 + 하위 단계(재귀)에서 얻은 리뷰를 합쳐 반환합니다.
const own = $('결과 정리').first().json.reviews || [];
const child = $input.all().map(i => i.json).filter(j => j && j.voc_id && j.content);

const uniq = new Map();
for (const r of [...own, ...child]) uniq.set(r.voc_id, r);
return [...uniq.values()].map(json => ({ json }));
